import type { StepId } from './onboarding';

export const TOUR_LOCALES = ['zh', 'zh-TW', 'en', 'vi'] as const;
export type TourLocale = typeof TOUR_LOCALES[number];
export type TourChapter = 'welcome' | 'profile' | 'sources' | 'feed' | 'ai' | 'youtube' | 'finish';
export type TourProvider = 'gemini' | 'groq' | 'nvidia' | 'cerebras' | 'openai' | 'deepseek' | 'glm' | 'custom';
export interface TourGuide { title: string; summary: string; steps: string[]; links: { label: string; url: string }[] }
export interface OnboardingMessages {
  steps: Record<StepId, { title: string; body: string }>;
  actions: Record<'launch' | 'start' | 'browse' | 'resume' | 'restart' | 'next' | 'back' | 'skip' | 'dismiss' | 'close' | 'openTarget' | 'refresh' | 'finish' | 'retry' | 'help' | 'official' | 'later', string>;
  status: Record<'viewed' | 'skipped' | 'configured' | 'verified' | 'notConfigured' | 'notVerified' | 'loading' | 'error' | 'complete' | 'progress' | 'saved' | 'pending' | 'unsaved' | 'saveFailed' | 'syncFailed' | 'noContent' | 'rateLimited' | 'reauth' | 'targetMissing' | 'progressUnavailable' | 'firstStep', string>;
  chapters: Record<TourChapter, string>;
  a11y: Record<'region' | 'chapter' | 'close' | 'progress' | 'externalLink' | 'checklist' | 'step' | 'firstStep', string>;
  errors: Record<'unauthorized' | 'forbidden' | 'model' | 'rateLimit' | 'quota' | 'parameters' | 'network' | 'conflict' | 'save' | 'progress', string>;
  help: Record<'welcome' | 'title' | 'summary' | 'dirtyConfirm' | 'unavailable' | 'privacy' | 'costWarning' | 'checkedAt' | 'verification', string>;
  guides: { ai: Record<TourProvider, TourGuide>; youtube: TourGuide };
}

// Exact host matching, not suffix matching; links are static official help, never user input.
export const OFFICIAL_ONBOARDING_HOSTS = [
  'accounts.google.com', 'support.google.com', 'console.cloud.google.com', 'developers.google.com',
  'docs.cloud.google.com', 'aistudio.google.com', 'ai.google.dev', 'console.groq.com',
  'build.nvidia.com', 'docs.api.nvidia.com', 'cloud.cerebras.ai', 'inference-docs.cerebras.ai',
  'www.cerebras.ai', 'platform.openai.com', 'openai.com', 'platform.deepseek.com',
  'api-docs.deepseek.com', 'bigmodel.cn', 'open.bigmodel.cn', 'docs.bigmodel.cn',
  'openrouter.ai', 'cloud.siliconflow.cn', 'platform.moonshot.cn',
] as const;
export function isOfficialOnboardingUrl(value: string): boolean {
  try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password && !url.port && (OFFICIAL_ONBOARDING_HOSTS as readonly string[]).includes(url.hostname); } catch { return false; }
}
const urls: Record<TourProvider | 'youtube', string[]> = {
  gemini: ['https://aistudio.google.com/apikey', 'https://aistudio.google.com/docs/get-started', 'https://ai.google.dev/gemini-api/docs/pricing'],
  groq: ['https://console.groq.com/login', 'https://console.groq.com/keys', 'https://console.groq.com/docs/rate-limits', 'https://console.groq.com/docs/billing-faqs'],
  nvidia: ['https://build.nvidia.com/explore/discover', 'https://docs.api.nvidia.com/nim/docs/api-quickstart'],
  cerebras: ['https://cloud.cerebras.ai', 'https://inference-docs.cerebras.ai/support/rate-limits.md', 'https://www.cerebras.ai/pricing'],
  openai: ['https://platform.openai.com/api-keys', 'https://openai.com/api/pricing/'],
  deepseek: ['https://platform.deepseek.com/api_keys', 'https://api-docs.deepseek.com/quick_start/pricing/'],
  glm: ['https://bigmodel.cn/usercenter/proj-mgmt/apikeys', 'https://docs.bigmodel.cn/cn/guide/start/model-overview'],
  custom: ['https://openrouter.ai/keys', 'https://cloud.siliconflow.cn/', 'https://platform.moonshot.cn/console/api-keys'],
  youtube: ['https://accounts.google.com/signup', 'https://console.cloud.google.com/', 'https://console.cloud.google.com/cloud-resource-manager', 'https://console.cloud.google.com/apis/library/youtube.googleapis.com', 'https://console.cloud.google.com/apis/credentials', 'https://developers.google.com/youtube/data/guides/authentication', 'https://docs.cloud.google.com/api-keys/docs/add-restrictions-api-keys'],
};
function guide(id: TourProvider | 'youtube', title: string, summary: string, steps: string[], labels: string[]): TourGuide {
  return { title, summary, steps, links: urls[id].map((url, i) => ({ label: labels[i]!, url })) };
}

